import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Rough Planning & Orientation","description":"","frontmatter":{"title":"Rough Planning & Orientation","cutting":"rough-planning"},"headers":[],"relativePath":"cutting/rough-planning.md","filePath":"cutting/rough-planning.md","lastUpdated":1790876393000}'),r={name:"cutting/rough-planning.md"};function o(s,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="rough-planning-orientation" tabindex="-1">Rough Planning &amp; Orientation <a class="header-anchor" href="#rough-planning-orientation" aria-label="Permalink to &quot;Rough Planning &amp; Orientation&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Cutting does not begin with choosing an attractive outline. The cutter first reads the rough: color zoning, fractures, inclusions, transparency, crystallographic direction, and possible optical phenomena. A plan balances weight retention, appearance, and durability, recording the table orientation, target outline, risks, and acceptable loss.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-rough-planning-en"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-rough-planning-en">Boundary &amp; Safety</h2><p>This page explains observation dimensions and design trade-offs in rough planning; it is not a cutting prescription and does not guarantee safety, durability, value, or commercial grade. A trained cutter must make the final orientation and process decision from the rough, equipment, and on-site risks. </p></aside><h2 id="case-flow" tabindex="-1">Case Flow <a class="header-anchor" href="#case-flow" aria-label="Permalink to &quot;Case Flow&quot;">​</a></h2><blockquote><p>Teaching case (demonstration): this is a recording method, not a cutting instruction for a real specimen.</p></blockquote><h3 id="_1-observe-the-input" tabindex="-1">1. Observe the input <a class="header-anchor" href="#_1-observe-the-input" aria-label="Permalink to &quot;1. Observe the input&quot;">​</a></h3><p>Record weight, outline, transparency, zoning, visible fractures, inclusions, crystallographic direction, and possible phenomena. Mark uncertain areas as “pending review” instead of turning a photo or impression into a conclusion.</p><h3 id="_2-keep-two-candidate-plans" tabindex="-1">2. Keep two candidate plans <a class="header-anchor" href="#_2-keep-two-candidate-plans" aria-label="Permalink to &quot;2. Keep two candidate plans&quot;">​</a></h3><p>Keep at least a weight-first plan and an appearance/durability-first plan. Record target outline, table direction, expected loss, risk zones, and rejection conditions for each so the trade-off is explainable.</p><h3 id="_3-review-and-record" tabindex="-1">3. Review and record <a class="header-anchor" href="#_3-review-and-record" aria-label="Permalink to &quot;3. Review and record&quot;">​</a></h3><p>Compare candidates under the same light, viewing direction, and record template. Re-check corners, thin girdles, fracture extension, and stress concentration. If the evidence is insufficient, keep the candidates open and do not cut.</p><h3 id="_4-stop-conditions" tabindex="-1">4. Stop conditions <a class="header-anchor" href="#_4-stop-conditions" aria-label="Permalink to &quot;4. Stop conditions&quot;">​</a></h3><p>Stop and ask a trained cutter to review when fracture risk, phenomenon orientation, or equipment safety cannot be established.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Inspect before sawing: clean, measure, and examine the rough under different lights and directions; mark fractures, inclusions, and color bands.</li><li>Prioritize orientation: with zoning, chatoyancy, asterism, or play of color, table direction controls how the effect is seen.</li><li>Make trade-offs explicit: retaining weight does not guarantee value; chasing weight can sacrifice brightness, symmetry, or durability.</li><li>Reserve a safety margin: avoid or reinforce corners, thin girdles, deep fractures, and stress concentrations in the design stage.</li><li>The final plan should explain why the stone was cut that way, not only describe its finished outline.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>opal</td><td>orient the face toward the strongest play of color</td><td>prioritise the strongest color patches</td></tr><tr><td>star sapphire</td><td>align the dome with the intersecting silk</td><td>centre the star at the dome</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA: Gem Cutting Styles — Definitions</a><span>Definitions of outlines, facet arrangements, step cuts, cabochons, and carving styles</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors and Cut Quality</a><span>Cut trade-offs among proportions, symmetry, polish, rough limitations, and appearance</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA: Diamond Cut</a><span>Round-brilliant table, crown, girdle, pavilion, and the 57/58-facet count</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>How colored-stone cutting weighs color, durability, inclusions, and fractures</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-rough-planning-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-rough-planning-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Rough planning balances weight retention, appearance, and durability.</span><small>GIA: Colored Gemstone Value Factors and Cut Quality; GIA: Emerald Quality Factors</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Orientation affects the presentation of zoning and phenomena such as asterism, chatoyancy, and play of color.</span><small>GIA: Gem Cutting Styles — Definitions</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>The teaching case records uncertainty in rough planning through two candidate plans and stop conditions.</span><small>GIA: Colored Gemstone Value Factors and Cut Quality; GIA: Emerald Quality Factors</small></li></ul></aside><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',21)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
